command:
$ErrorActionPreference="Stop"
$main="03e4328f3cae43d156cac6c643fa837fd33f7ebc"
$candidate="6949b39a11fec8608468fa3edb460bb93eb33b7e"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$baseline=Join-Path $env:RUNNER_TEMP "fly-v3-ext-main-before-03e4328"
$changed=Join-Path $env:RUNNER_TEMP "fly-v3-ext-candidate-after-6949b39"
if((Test-Path -LiteralPath $baseline) -or (Test-Path -LiteralPath $changed)){throw "Owned worktree collision"}
Set-Location -LiteralPath $repo
& git fetch origin main feat/search-v3-indexed-extension-integration --no-tags
if($LASTEXITCODE -ne 0){throw "Git fetch failed"}
$observed=(& git rev-parse refs/remotes/origin/main).Trim()
if($LASTEXITCODE -ne 0 -or $observed -ne $main){throw "Main changed"}
$branch=(& git rev-parse refs/remotes/origin/feat/search-v3-indexed-extension-integration).Trim()
if($LASTEXITCODE -ne 0 -or $branch -ne $candidate){throw "Candidate ref changed"}
try {
  & git worktree add --detach $baseline $main
  if($LASTEXITCODE -ne 0){throw "Baseline worktree failed"}
  & git worktree add --detach $changed $candidate
  if($LASTEXITCODE -ne 0){throw "Candidate worktree failed"}
  Set-Location -LiteralPath $baseline
  & cmd.exe /c build.bat Release
  if($LASTEXITCODE -ne 0){throw "INDEXED_VISUAL_BASELINE_BUILD_FAILED"}
  Write-Host "INDEXED_VISUAL_BASELINE_BUILD=PASS"
  Set-Location -LiteralPath $changed
  & cmd.exe /c build.bat Release
  if($LASTEXITCODE -ne 0){throw "INDEXED_VISUAL_CANDIDATE_BUILD_FAILED"}
  Write-Host "INDEXED_VISUAL_CANDIDATE_BUILD=PASS"
  $env:FLY_INDEXED_SEARCH_VISUAL_EXE=Join-Path $baseline "out\winui\Release\flyExplorer.exe"
  & python -X utf8 tests/winui/test_indexed_search_gui.py --configuration Release --capture before
  if($LASTEXITCODE -ne 0){throw "INDEXED_VISUAL_BASELINE_CAPTURE_FAILED"}
  Write-Host "INDEXED_VISUAL_BASELINE_CAPTURE=PASS"
  Remove-Item Env:FLY_INDEXED_SEARCH_VISUAL_EXE -ErrorAction SilentlyContinue
  & python -X utf8 tests/winui/test_indexed_search_gui.py --configuration Release --capture after
  if($LASTEXITCODE -ne 0){throw "INDEXED_VISUAL_CANDIDATE_GUI_FAILED"}
  Write-Host "INDEXED_VISUAL_CANDIDATE_GUI=PASS"
  $images=Join-Path $changed "logs\search-v3-indexed"
  & python -X utf8 tests/winui/indexed_search_visual_compare.py --before (Join-Path $images "indexed-search-before.bmp") --after (Join-Path $images "indexed-search-after.bmp") --metadata (Join-Path $images "visual-comparison.json")
  if($LASTEXITCODE -ne 0){throw "INDEXED_VISUAL_COMPARISON_FAILED"}
  Write-Host "INDEXED_VISUAL_CAPTURE_AND_COMPARE=PASS"
} finally {
  Remove-Item Env:FLY_INDEXED_SEARCH_VISUAL_EXE -ErrorAction SilentlyContinue
  Set-Location -LiteralPath $repo
  if(Test-Path -LiteralPath $changed){& git worktree remove --force $changed}
  if(Test-Path -LiteralPath $baseline){& git worktree remove --force $baseline}
  & git worktree prune
}
